nginx.conf.text:
# Reverse proxy for the billing service
upstream billing_backend {
    server 10.20.30.41:8080 max_fails=3;
    server 10.20.30.42:8080 max_fails=3;
}

server {
    listen 443 ssl http2;
    server_name billing.example.com;

    ssl_certificate     /etc/nginx/certs/billing.example.com.crt;
    ssl_certificate_key /etc/nginx/certs/billing.example.com.key;

    access_log /var/log/nginx/billing.access.log;
    client_max_body_size 25m;

    location / {
        proxy_pass http://billing_backend;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
    }

    location /static/ {
        root /srv/billing/public;
        expires 7d;
    }
}
